const e="acoustica-inter-school-solo-singing",l=2026,t="Built from the organiser's 2026 rules document and its student and school registration forms. The heading prints the date 10/01/2026 without saying whether it is 10 January or 1 October; the registration deadline of 20/12/2025 suggests 10 January 2026, but this is not stated. The event venue and time are not printed. The song language line in the source still reads 'Specify Language' (template text left in). Ages are not printed, only classes. Bank or personal data: none printed.",n={Title:"Rules & Criteria",Subtitle:"Acoustica 2026 inter-school solo singing competition",NoticeTitle:"Please Read Before Registering",Notice:"Registration closes on {{RegistrationDeadline}}. Late entries are not accepted. There is no fee.",Notes:["Backing tracks (MP3) must reach the organisers at least 24 hours before the event.","The event date may be postponed; the school will inform participants."],Sections:[{Key:"general",Title:"General rules",Items:["The competition is strictly for solo singers. No duets or group performances are allowed.","The date of the event may be postponed in any circumstance. The school will inform participants.","The event date printed in the rules is {{EventDate}}."]},{Key:"eligibility",Title:"Who can enter",Items:["Only bonafide students enrolled in a school can enter (the rules call it an inter-school competition).","Junior category is for classes 7 to 9. Senior category is for classes 10 to 12.","Each school may send at most 4 entries in total.","Each school may send at most 2 entries in each category (Junior and Senior).","The school principal or head must certify that the listed students are bonafide students authorised to represent the school."]},{Key:"registration",Title:"How to register",Items:["Fill in the student registration form for each singer and the school registration form for the school.","Submit the forms to the school in person, or email the scanned forms to {{SchoolEmail}}, and inform the event in-charge.","The registration forms and the song details (title, artist, language, duration) must reach the organisers by {{RegistrationDeadline}}.","Each school names one teacher or coordinator as the single point of contact (SPOC), with designation, mobile number and email.","The student form asks for full name, age, class, school, email, mobile number, song title, original artist or composer, song language, performance genre and the accompaniment choice (karaoke track or a cappella).","The singer and the guardian sign a declaration that they have read and agree to the rules, including the limits on accompaniment and time."]},{Key:"fees",Title:"Fees",Items:["{{EntryFee}}"]},{Key:"conduct",Title:"Song choice and conduct",Items:["The theme covers three genres: Bollywood hits, Classical, and Western Pop and Rock. The song must suit the chosen theme.","The song must be in Hindi, English or any recognised Indian regional language.","Song lyrics and themes must suit a school-level audience.","Explicit, vulgar, or politically or religiously offensive language or content leads to immediate disqualification.","A singer must keep to the song submitted at registration.","A change of song must be told to the organisers at least 48 hours before the performance and needs the organisers' approval."]},{Key:"judging",Title:"Judging",Items:["The judges' decision is final and binding on all participants.","Judging uses these criteria and recommended weightage: Vocal Quality and Technique 40, Rhythm and Timing (Laya) 20, Expression and Musicality 20, Stage Presence and Confidence 10, Choice of Song 10."]},{Key:"prizes",Title:"Awards",Items:["A Winner and a Runner-Up are awarded in each category (Junior and Senior)."]},{Key:"other",Title:"Disqualification",Items:["A singer may be disqualified immediately for using a backing track with pre-recorded vocals.","A singer may be disqualified immediately for indiscipline, misbehaviour or disrespect to the judges, organisers or other participants.","A singer may be disqualified immediately for performing a song with vulgar, offensive or inappropriate content."]}],Documents:[{Title:"Rules and registration forms (PDF)",Url:"https://shreejkpublicschool.com/wp-content/uploads/Rules-Regulations_-Inter-School-Solo-Singing-Competition-2.pdf"}]},o=[],i=[],a=[{Title:"Solo Singing",Source:"Rules and Regulations",Sections:{About:["A solo vocal performance."],TimeAndFormat:["Each singer has a maximum of 5 minutes. This includes set-up time such as walking on and adjusting the microphone.","A penalty of 1 mark per 10 seconds is deducted for going over the time limit."],Rules:["Backing tracks must be sent to the organisers in MP3 format at least 24 hours before the event."],Allowed:["A pre-recorded instrumental (karaoke) track.","Singing a cappella, without any music."],NotAllowed:["A backing track with pre-recorded vocals, backing harmonies or chorus vocals. This means immediate disqualification.","Looking at the lyrics during the performance. The song must be sung from memory."],Judging:["Vocal Quality and Technique (pitch accuracy, tone, control, range, breath support): 40.","Rhythm and Timing (Laya) (tempo, rhythm, sync with the track or accompanist): 20.","Expression and Musicality (emotional connect, interpretation, dynamics): 20.","Stage Presence and Confidence (engagement, stage movement, persona): 10.","Choice of Song (suitability and challenge level for the singer's voice and the theme): 10."],Points:null,Notes:null},Markdown:`## About this competition
- A solo vocal performance.

## Time and format
- Each singer has a maximum of 5 minutes. This includes set-up time such as walking on and adjusting the microphone.
- A penalty of 1 mark per 10 seconds is deducted for going over the time limit.

## Rules
- Backing tracks must be sent to the organisers in MP3 format at least 24 hours before the event.

## Allowed
- A pre-recorded instrumental (karaoke) track.
- Singing a cappella, without any music.

## Not allowed
- A backing track with pre-recorded vocals, backing harmonies or chorus vocals. This means immediate disqualification.
- Looking at the lyrics during the performance. The song must be sung from memory.

## Judging
- Vocal Quality and Technique (pitch accuracy, tone, control, range, breath support): 40.
- Rhythm and Timing (Laya) (tempo, rhythm, sync with the track or accompanist): 20.
- Expression and Musicality (emotional connect, interpretation, dynamics): 20.
- Stage Presence and Confidence (engagement, stage movement, persona): 10.
- Choice of Song (suitability and challenge level for the singer's voice and the theme): 10.`}],s=[],r=[{Key:"RegistrationDeadline",Kind:"date",Label:"Last date to register",Value:"2025-12-20",Source:"Rules 1. General Eligibility and Registration"},{Key:"EventDate",Kind:"text",Label:"Event date as printed",Value:"10/01/2026 (printed in the heading; day and month order not stated)",Source:"Rules heading"},{Key:"EntryFee",Kind:"fee",Label:"Entry fee",Value:"There is no fee for registration and participation.",Source:"Rules 1"},{Key:"SchoolEmail",Kind:"text",Label:"Email for scanned registration forms",Value:"shreejkpublicschool@gmail.com",Source:"Registration note"},{Key:"EventCoordinator",Kind:"contact",Label:"Event in-charge and coordinator",Value:{Name:"Mahendra Sir",Role:"Event Incharge and Coordinator",Phone:"9827216120",WhatsApp:"",Email:"shreejkpublicschool@gmail.com"},Source:"Registration note"}],c=[{Claim:"Rules, eligibility, registration, judging criteria, awards and forms for the Acoustica 2026 inter-school solo singing competition.",SourceType:"Primary - the event's own rules document",Source:"Acoustica 2026 Rules & Regulations: Inter-School Solo Singing Competition",Url:"https://shreejkpublicschool.com/wp-content/uploads/Rules-Regulations_-Inter-School-Solo-Singing-Competition-2.pdf"}],h={TemplateKey:e,Year:2026,Note:t,Page:n,ParticipantTypes:o,AgeGroups:i,Competitions:a,CompetitionAgeGroups:s,Variables:r,Evidence:c};export{i as AgeGroups,s as CompetitionAgeGroups,a as Competitions,c as Evidence,t as Note,n as Page,o as ParticipantTypes,e as TemplateKey,r as Variables,l as Year,h as default};
